private TreeNode<T> rotateRight(TreeNode<T> node){
    if(node == null || node.leftChild == null){
        return node; // No rotation needed for invalid or right-child-only nodes.
    }

    // Place the right child of node to the left of node
    TreeNode<T> temp = node.leftChild;
    node.leftChild = temp.rightChild;
    temp.rightChild = node;

    // Update child pointers to keep the parent-child relationships intact
    temp.leftChild.parent = node;
    node.parent = temp;

    // Return the new parent of node
    return temp;
}

